        },
        {
          "id": "C2-05",
          "zh": "身体还在发抖"
        },
        {
          "id": "C2-06",
          "zh": "把自己抱得更紧"
        },
        {
          "id": "C2-07",
          "zh": "攥着觉悟踏出去"
        },
        {
          "id": "C2-08",
          "zh": "我想要实现的梦 现在就要亲手夺回来"
        }
      ]
    },
