      "label": "D",
      "phrases": [
        {
          "id": "C2-01",
          "zh": "即使明天是"
        },
        {
          "id": "C2-02",
          "zh": "死路一条也"
        },
        {
          "id": "C2-03",
          "zh": "用自己双手"
        },
        {
          "id": "C2-04",
          "zh": "去开辟道路"
        },
        {
          "id": "C2-05",
          "zh": "颤抖的身躯"
        },
        {
          "id": "C2-06",
          "zh": "紧紧拥抱住"
